完美！现在我已经理解了整个 `OpenLevelCo` 的结构。让我为您提供完整的实现方案。

## 分析结果

**目标函数:**
- 类: `scnEditor` (Assembly-CSharp.dll)
- 方法: `OpenLevelCo(String definedLevelPath)` - 这是一个私有协程 (IEnumerator)
- 公开接口: `OpenLevel(String filePath)` 和 `OpenLevel()`（后者会调用 `OpenFilePanelAndroid`）

**原工作流程:**
1. 用户点击"打开"按钮
2. 调用 `OpenLevel()` 或 `OpenLevel(String path)`
3. `OpenLevel()` → `OpenFilePanelAndroid()` (Android 文件选择器)
4. 用户选择文件后，回调调用 `OpenLevelCo(selectedPath)`

**我们要修改:**
钩住 `OpenLevelCo` 方法，在其中调用 Android 系统文件选择器，获取用户选择的文件路径，然后传递给原始函数。

## 实现步骤

### 1. 在 Main.cpp 中添加钩子函数

```cpp
#include <jni.h>
#include "universe.h"
#include <sys/mman.h>
#include <unistd.h>
// 添加 JNI 相关的头文件
#include <string>

// 声明全局原函数指针
private IEnumerator* (*old_OpenLevelCo)(UnityEngine::Object* instance, String* definedLevelPath);

// JNI 回调：从 Java 获取文件路径并调用 OpenLevelCo
jstring g_selectedPath = nullptr;
UnityEngine::Object* g_scnEditorInstance = nullptr;

extern "C" JNIEXPORT void JNICALL
Java_com_example_application_FilePickerCallback_onFileSelected(JNIEnv* env, jobject thiz, jstring path) {
    const char* cPath = env->GetStringUTFChars(path, nullptr);
    if (cPath) {
        g_selectedPath = CreateMonoString(cPath);
        env->ReleaseStringUTFChars(path, cPath);
    }

    // 如果编辑器实例存在且路径有效，调用 OpenLevelCo
    if (g_scnEditorInstance && g_selectedPath) {
        // 获取当前 scnEditor 实例
        Class scnEditorClass = Class("", "scnEditor");
        Method<IEnumerator*> openLevelCoMethod = scnEditorClass.GetMethod("OpenLevelCo", 1);

        // 调用原始协程（通过钩子函数）
        IEnumerator* enumerator = openLevelCoMethod[g_scnEditorInstance].Call(g_selectedPath);

        // 清理
        g_selectedPath = nullptr;
    }
}

// 钩子函数实现
private IEnumerator* OpenLevelCo_Hook(UnityEngine::Object* instance, String* definedLevelPath) {
    // 保存 scnEditor 实例，供 Java 回调使用
    g_scnEditorInstance = instance;

    // 调用 Java 端打开文件选择器
    JNIEnv* env = nullptr;
    JavaVM* vm = nullptr;
    // 假设您已保存 JavaVM 指针（在 JNI_OnLoad 中获取）
    // vm->AttachCurrentThread(&env, nullptr);

    jclass activityClass = env->GetObjectClass(/* your activity instance */);
    jmethodID showFilePicker = env->GetMethodID(activityClass, 
        "showFilePicker", "()V");
    env->CallVoidMethod(/* activity instance */, showFilePicker);

    // 注意：路径将在 Java 回调中处理，这里返回 null 或保持原逻辑
    // 如果想完全重写，可以在这里不调用原函数，稍后由回调触发

    // 如果不希望原函数立即执行，可以返回 nullptr
    return nullptr;

    // 或者：如果想保持原逻辑但修改路径，可以这样：
    // return old_OpenLevelCo(instance, definedLevelPath);
}

// 在 start() 函数中注册钩子
void start() {
    // ... 之前的钩子代码 ...

    // 注册 OpenLevelCo 钩子
    auto openLevelCoMethod = Class("", "scnEditor").GetMethod("OpenLevelCo", 1);
    BasicHook(openLevelCoMethod, OpenLevelCo_Hook, old_OpenLevelCo);
}
```

### 2. Java 端 Activity 添加文件选择器

```java
// app/src/main/java/com/example/application/MainActivity.java (或对应 Activity)
package com.example.application;

import android.app.Activity;
import android.content.Intent;
import android.net.Uri;

public class MainActivity extends UnityPlayerActivity {

    static {
        System.loadLibrary("October");
    }

    // 原生方法声明
    private native void onFileSelected(String path);

    public void showFilePicker() {
        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        intent.addCategory(Intent.CATEGORY_OPENABLE);
        intent.setType("text/plain"); // 或 "*/*" 支持所有文件
        // ADOFAI 关卡文件通常是 .adofai 扩展名
        intent.putExtra(Intent.EXTRA_MIME_TYPES, new String[]{"application/octet-stream", "text/plain"});
        startActivityForResult(intent, 1001);
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);

        if (requestCode == 1001 && resultCode == Activity.RESULT_OK) {
            Uri uri = data.getData();
            if (uri != null) {
                // 获取实际文件路径（需要处理权限）
                String path = getRealPathFromURI(uri);
                onFileSelected(path);
            }
        }
    }

    private String getRealPathFromURI(Uri uri) {
        // 实现路径解析逻辑
        // 可以使用 ContentResolver 读取文件
        String[] projection = { android.provider.MediaStore.MediaColumns.DATA };
        // ... 完整实现
        return uri.getPath(); // 简化版，实际需要更复杂的处理
    }
}
```

### 3. 调整 Android.mk 链接 Java 类

确保在 `Android.mk` 中添加 JNI 绑定：

```makefile
LOCAL_MODULE := October
LOCAL_SRC_FILES := ... Main.cpp

# 添加 JNI 导出
LOCAL_LDLIBS := -llog -landroid
```

### 4. Important Notes

1. **协程处理**: `OpenLevelCo` 返回 `IEnumerator`，需要正确管理协程生命周期
2. **线程切换**: JNI 回调可能在另一个线程，注意线程安全
3. **路径格式**: Android 使用 `/storage/emulated/0/...` 而非 `D:\...`
4. **权限**: 需要 `READ_EXTERNAL_STORAGE` 权限（已有）
5. **Mono 字符串**: 使用 `CreateMonoString()` 转换 char* 到 C# String*

