static std::condition_variable g_pickerCV;
static bool g_pickerDone = false;
static std::string g_selectedPath; // 结果

// JNI 回调（Java 调用）
extern "C" JNIEXPORT void JNICALL
Java_com_mod_filepicker_FilePicker_nativeOnFileSelected(JNIEnv* env, jclass, jstring jpath) {
    const char* path = env->GetStringUTFChars(jpath, nullptr);
    {
        std::lock_guard<std::mutex> lock(g_pickerMutex);
        g_selectedPath = path ? path : "";
        g_pickerDone = true;
    }
    env->ReleaseStringUTFChars(jpath, path);
    g_pickerCV.notify_one();
}

// 调用 Java 文件选择器
void ShowAndroidFilePicker(JNIEnv* env) {
    jclass pickerCls = env->FindClass("com/mod/filepicker/FilePicker");
    jmethodID showMethod = env->GetStaticMethodID(pickerCls, "show", "()V");
    env->CallStaticVoidMethod(pickerCls, showMethod);
    env->DeleteLocalRef(pickerCls);
}

// Hook: scnEditor.OpenLevel()
void Hooked_OpenLevel(Il2CppObject* editor) {
    JNIEnv* env = nullptr;
    g_vm->AttachCurrentThread(&env, nullptr);

    // 重置状态
    {
        std::lock_guard<std::mutex> lock(g_pickerMutex);
        g_pickerDone = false;
        g_selectedPath.clear();
    }

    // 调 Java 选择器
    ShowAndroidFilePicker(env);

    // 阻塞等待结果
    std::unique_lock<std::mutex> lock(g_pickerMutex);
    g_pickerCV.wait(lock, []{ return g_pickerDone; });

    if (!g_selectedPath.empty()) {
        // 调用 scnEditor.OpenLevel(string)
        auto editorClass = BNM::Class("Assembly-CSharp", "scnEditor");
        auto openLevelStr = editorClass.GetMethod("OpenLevel", {"filePath"});
        openLevelStr[editor].Call(g_selectedPath.c_str());
    } else {
        LOGD("File picker cancelled or failed");
    }
}

// 初始化
void start() {
    // 原有逻辑保留...

    // Hook OpenLevel
    auto openLevelMethod = Class("Assembly-CSharp", "scnEditor").GetMethod("OpenLevel");
    BNM::Hook::Attach(openLevelMethod, Hooked_OpenLevel);
}
