// ============ 初始化 Java FilePicker 类 ============
void InitJavaFilePicker(JNIEnv* env) {
    LOGD("Initializing Java FilePicker...");

    // 查找类
    jclass localClass = env->FindClass("com/mod/filepicker/FilePicker");
    if (!localClass) {
        LOGE("FilePicker class not found!");
        return;
    }

    // 缓存方法 ID
    g_initMethodID = env->GetStaticMethodID(localClass, "initialize",
                                            "(Landroid/app/Activity;J)V");
    g_showMethodID = env->GetStaticMethodID(localClass, "show", "()V");

    if (!g_initMethodID || !g_showMethodID) {
        LOGE("Failed to get FilePicker method IDs");
        env->DeleteLocalRef(localClass);
        return;
    }

    // 保存全局类引用（避免局部引用被释放）
    g_javaFilePickerClass = env->NewGlobalRef(localClass);
    env->DeleteLocalRef(localClass);

    // 获取 UnityPlayer.currentActivity
    jclass unityPlayerCls = env->FindClass("com/unity3d/player/UnityPlayer");
    if (!unityPlayerCls) {
        LOGE("UnityPlayer class not found!");
        return;
    }
    jfieldID activityField = env->GetStaticFieldID(unityPlayerCls,
                                                   "currentActivity",
                                                   "Landroid/app/Activity;");
    jobject activity = env->GetStaticObjectField(unityPlayerCls, activityField);

    if (activity) {
        // 调用 FilePicker.initialize(activity, 0)
        env->CallStaticVoidMethod(g_javaFilePickerClass, g_initMethodID,
                                  activity, (jlong)0);
        LOGD("FilePicker initialized");
    } else {
        LOGE("Failed to get UnityPlayer.currentActivity");
    }

    env->DeleteLocalRef(unityPlayerCls);
    if (activity) env->DeleteLocalRef(activity);
}

